INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(44761, 'Exodus 36:12', 'Exodus', 36, 12, 'همدارنګه هغوی پنځوس کړۍ ګانې په یوې پردې باندې او پنځوس د بلې جوړې په اخرنۍ پردې باندې په داسې ډول جوړې کړلې چې هغه کړۍ ګانې یو بل ته مخامخ وي.', 'همدارنګه هغوی پنجوس کری ګانې په یوې پردې باندې او پنجوس د بلې جورې په اخرنی پردې باندې په داسې دول جورې کرلې چې هغه کری ګانې یو بل ته مخامخ وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44762, 'Exodus 36:13', 'Exodus', 36, 13, 'بیا هغوی پنځوس د سرو زرو چنګکونه جوړ کړل او د پردو د دوه جوړو په یوځای تړلو کې یې ورڅخه کار واخیست، ترڅو ټوله یوه خېمه ورڅخه جوړه شي.', 'بیا هغوی پنجوس د سرو زرو چنګکونه جور کرل او د پردو د دوه جورو په یوجای ترلو کې یې ورچخه کار واخیست، ترچو توله یوه خېمه ورچخه جوره شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44763, 'Exodus 36:14', 'Exodus', 36, 14, 'هغوی د سپېڅلې خېمې د پوښ دپاره د وزو د وړیو څخه پردې جوړې کړې چې ټولې یوولس دانې وې.', 'هغوی د سپېچلې خېمې د پوش دپاره د وزو د وریو چخه پردې جورې کرې چې تولې یوولس دانې وې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44764, 'Exodus 36:15', 'Exodus', 36, 15, 'یوولس واړه پردې په یوه اندازه وې، یعنې دیارلس متره اوږدې او دوه متره پلنې وې.', 'یوولس واره پردې په یوه اندازه وې، یعنې دیارلس متره اوزدې او دوه متره پلنې وې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44765, 'Exodus 36:16', 'Exodus', 36, 16, 'هغوی پنځه پردې په یوه جوړه کې سره یوځای کړې او نورې شپږ یې په بله جوړه کې.', 'هغوی پنجه پردې په یوه جوره کې سره یوجای کرې او نورې شپز یې په بله جوره کې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44766, 'Exodus 36:17', 'Exodus', 36, 17, 'بیا یې پنځوس کړۍ ګانې د یوې جوړې د اخرنۍ پردې په څنډه کې جوړې کړلې او د بلې جوړې د اخرنۍ پردې په څنډه کې یې همداسې جوړې کړلې.', 'بیا یې پنجوس کری ګانې د یوې جورې د اخرنی پردې په چنده کې جورې کرلې او د بلې جورې د اخرنی پردې په چنده کې یې همداسې جورې کرلې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_17.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44767, 'Exodus 36:18', 'Exodus', 36, 18, 'د برنجو پنځوس چنګکونه یې جوړ کړل او په کړۍ ګانو کې یې واچول چې خېمه یوځای سره وتړي.', 'د برنجو پنجوس چنګکونه یې جور کرل او په کری ګانو کې یې واچول چې خېمه یوجای سره وتری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44768, 'Exodus 36:19', 'Exodus', 36, 19, 'بیا یې د خېمې دپاره د پسه د داسې پوستکي څخه پوښ جوړ کړ چې سور رنګ ورکړل شوی ؤ او په هغه باندې یې د ښې څرمنې څخه یو پوښ جوړ کړ.', 'بیا یې د خېمې دپاره د پسه د داسې پوستکی چخه پوش جور کر چې سور رنګ ورکرل شوی و او په هغه باندې یې د شې چرمنې چخه یو پوش جور کر.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44769, 'Exodus 36:20', 'Exodus', 36, 20, 'هغوی د خېمې دپاره د اکاسۍ د لرګي څخه ولاړ چوکاټونه جوړ کړل.', 'هغوی د خېمې دپاره د اکاسی د لرګی چخه ولار چوکاتونه جور کرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_20.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44770, 'Exodus 36:21', 'Exodus', 36, 21, 'هر چوکاټ څلورنیم متره اوږد او پنځه شپېته سانتي پلن ؤ،', 'هر چوکات چلورنیم متره اوزد او پنجه شپېته سانتی پلن و،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_21.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44771, 'Exodus 36:22', 'Exodus', 36, 22, 'دوه یوشان نښلوونکې تختې یې درلودلې، ترڅو چوکاټونه سره یوځای شي. ټولو چوکاټونو دا تختې درلودلې.', 'دوه یوشان نشلوونکې تختې یې درلودلې، ترچو چوکاتونه سره یوجای شی. تولو چوکاتونو دا تختې درلودلې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_36_22.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44772, 'Exodus 36:23', 'Exodus', 36, 23, 'هغوی د خېمې د جنوب خوا دپاره شل چوکاټونه جوړ کړل،', 'هغوی د خېمې د جنوب خوا دپاره شل چوکاتونه جور کرل،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_36_23.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44773, 'Exodus 36:24', 'Exodus', 36, 24, 'او څلوېښت د سپینو زرو پایې یې جوړې کړې چې ورلاندې شي، د هر چوکاټ لاندې دوه دوه پایې وې، د دې دپاره چې دوه تختې یې ونیسي.', 'او چلوېشت د سپینو زرو پایې یې جورې کرې چې ورلاندې شی، د هر چوکات لاندې دوه دوه پایې وې، د دې دپاره چې دوه تختې یې ونیسی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44774, 'Exodus 36:25', 'Exodus', 36, 25, 'هغوی د بلې خوا یعنې د خېمې د شمال خوا دپاره شل چوکاټونه جوړ کړل،', 'هغوی د بلې خوا یعنې د خېمې د شمال خوا دپاره شل چوکاتونه جور کرل،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_25.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44775, 'Exodus 36:26', 'Exodus', 36, 26, 'او څلوېښت د سپینو زرو پایې یې جوړې کړلې چې د هر چوکاټ لاندې دوه دوه وي.', 'او چلوېشت د سپینو زرو پایې یې جورې کرلې چې د هر چوکات لاندې دوه دوه وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_26.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44776, 'Exodus 36:27', 'Exodus', 36, 27, 'د خېمې د شا دپاره یې چې د لوېدیځ خواته وه، شپږ چوکاټونه جوړ کړل،', 'د خېمې د شا دپاره یې چې د لوېدیج خواته وه، شپز چوکاتونه جور کرل،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_27.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44777, 'Exodus 36:28', 'Exodus', 36, 28, 'او دوه چوکاټونه یې د خېمې د شاتني کنجونو دپاره جوړ کړل.', 'او دوه چوکاتونه یې د خېمې د شاتنی کنجونو دپاره جور کرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_28.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44778, 'Exodus 36:29', 'Exodus', 36, 29, 'په دغو دوو کنجونو کې هغه چوکاټونه د بېخ څخه نیولې تر سره پورې سره یوځای وو او په یوې کړۍ کې لګول شوي وو، دا دواړه یوشان وو.', 'په دغو دوو کنجونو کې هغه چوکاتونه د بېخ چخه نیولې تر سره پورې سره یوجای وو او په یوې کری کې لګول شوی وو، دا دواره یوشان وو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44779, 'Exodus 36:30', 'Exodus', 36, 30, 'نو اته چوکاټونه او شپاړس د سپینو زرو پایې وې، د هر چوکاټ لاندې دوه دوه پایې وې.', 'نو اته چوکاتونه او شپارس د سپینو زرو پایې وې، د هر چوکات لاندې دوه دوه پایې وې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_30.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44780, 'Exodus 36:31', 'Exodus', 36, 31, 'هغوی د اکاسۍ د لرګي څخه پنځلس اړمونه جوړ کړل، پنځه یې د هغو چوکاټونو دپاره جوړ کړل چې د خېمې په یوې خوا باندې وو،', 'هغوی د اکاسی د لرګی چخه پنجلس ارمونه جور کرل، پنجه یې د هغو چوکاتونو دپاره جور کرل چې د خېمې په یوې خوا باندې وو،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_31.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44781, 'Exodus 36:32', 'Exodus', 36, 32, 'پنځه د هغو چوکاټونو دپاره چې په بلې خوا باندې وو او پنځه د هغو چوکاټونو دپاره چې شاته د لوېدیځ خواته په اخر سر کې وو.', 'پنجه د هغو چوکاتونو دپاره چې په بلې خوا باندې وو او پنجه د هغو چوکاتونو دپاره چې شاته د لوېدیج خواته په اخر سر کې وو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_32.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44782, 'Exodus 36:33', 'Exodus', 36, 33, 'منځنی اړم چې د چوکاټونو تر نیمایي پورې ایښودل شوی ؤ، هغه د خېمې د یو سر څخه تر بل سره پورې غزېدلی ؤ.', 'منجنی ارم چې د چوکاتونو تر نیمایی پورې ایشودل شوی و، هغه د خېمې د یو سر چخه تر بل سره پورې غزېدلی و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_33.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44783, 'Exodus 36:34', 'Exodus', 36, 34, 'چوکاټونو ته یې د سرو زرو پوښ ورکړ او د سرو زرو کړیو سره یې ولګول چې اړمونه ونیسي. همدارنګه هغوی اړمونو ته هم د سرو زرو پوښ ورکړ.', 'چوکاتونو ته یې د سرو زرو پوش ورکر او د سرو زرو کریو سره یې ولګول چې ارمونه ونیسی. همدارنګه هغوی ارمونو ته هم د سرو زرو پوش ورکر.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_36_34.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44784, 'Exodus 36:35', 'Exodus', 36, 35, 'هغوی د ښه کتان او ابي، بانجاني او سرو وړیو څخه یوه پرده جوړه کړه او په هغې کې یې د اسماني مخلوقاتو نقشونه ګلدوزي کړی ؤ.', 'هغوی د شه کتان او ابی، بانجانی او سرو وریو چخه یوه پرده جوره کره او په هغې کې یې د اسمانی مخلوقاتو نقشونه ګلدوزی کری و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_35.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44785, 'Exodus 36:36', 'Exodus', 36, 36, 'د هغې دپاره یې د اکاسۍ د لرګي څخه څلور ستنې جوړې کړې او د سرو زرو پوښ یې ورته ورکړ او د هغو دپاره یې د سرو زرو چنګکونه جوړ کړل او څلور پایې یې ورته جوړې کړې.', 'د هغې دپاره یې د اکاسی د لرګی چخه چلور ستنې جورې کرې او د سرو زرو پوش یې ورته ورکر او د هغو دپاره یې د سرو زرو چنګکونه جور کرل او چلور پایې یې ورته جورې کرې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_36_36.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44786, 'Exodus 36:37', 'Exodus', 36, 37, 'هغوی د خېمې د دروازې دپاره د ابي، بانجاني او سرو وړیو او د ښه کتان څخه یوه پرده جوړه کړه چې ګلدوزي شوې وه.', 'هغوی د خېمې د دروازې دپاره د ابی، بانجانی او سرو وریو او د شه کتان چخه یوه پرده جوره کره چې ګلدوزی شوې وه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_36_37.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44787, 'Exodus 36:38', 'Exodus', 36, 38, 'د دې پردې دپاره هغوی پنځه ستنې جوړې کړې چې د چنګکونو سره لګېدلې وې، د هغو سرونو او سیخونو ته یې د سرو زرو پوښ ورکړ او د ستنو دپاره یې پنځه برنجي پایې جوړې کړلې.', 'د دې پردې دپاره هغوی پنجه ستنې جورې کرې چې د چنګکونو سره لګېدلې وې، د هغو سرونو او سیخونو ته یې د سرو زرو پوش ورکر او د ستنو دپاره یې پنجه برنجی پایې جورې کرلې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_36_38.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44788, 'Exodus 27:1', 'Exodus', 27, 1, 'د اکاسۍ د لرګي څخه د قربانۍ یو ځای جوړ کړه چې یو متر او دېرش سانتي لوړ وي. هغه دې څلور کنجه وي، دوه متره او شل سانتي دې اوږد وي او دوه متره او شل سانتي دې پلن وي.', 'د اکاسی د لرګی چخه د قربانی یو جای جور کره چې یو متر او دېرش سانتی لور وی. هغه دې چلور کنجه وی، دوه متره او شل سانتی دې اوزد وی او دوه متره او شل سانتی دې پلن وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_27_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
